# 150 Plan › Plans: the client's ONE current program with a workout part and a nutrition part (redesign 22 Oct); versions table unchanged in content
from cw import *
X='''.prog{background:#fff;border:1px solid var(--border);border-radius:20px;overflow:hidden}
.prog .prh{display:flex;align-items:center;gap:14px;padding:16px 20px;background:linear-gradient(90deg,var(--lavender-50),#fff);border-bottom:1px solid var(--border)}
.part{display:grid;grid-template-columns:240px 1fr 130px;gap:20px;align-items:center;padding:16px 20px}.part+.part{border-top:1px dashed var(--border-strong)}
.part .pl{display:flex;gap:12px;align-items:flex-start}.part .pi{width:40px;height:40px;border-radius:12px;background:var(--lavender);color:var(--indigo);display:flex;align-items:center;justify-content:center;flex:none}
.part .pl b{display:block;font-size:12px;letter-spacing:.4px;color:var(--ink-500);font-weight:700}.part .pl strong{display:block;font-size:16px;color:var(--navy);font-weight:600;margin-top:2px}.part .pl span{font-size:12px;color:var(--ink-500)}
.days{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}.days div{border:1px solid var(--border);border-radius:10px;padding:7px 9px;font-size:12px;color:var(--ink-500);background:#fff}.days div b{display:block;font-size:13px;color:var(--navy);font-weight:600}.days div.rs{background:var(--neu-bg)}.days div.td{border-color:var(--indigo);box-shadow:inset 0 0 0 1px var(--indigo)}
table{width:100%;border-collapse:collapse;font-size:14px}th{text-align:left;font-size:12px;color:var(--ink-500);font-weight:600;padding:10px 16px;background:var(--hover);border-top:1px solid var(--border)}td{padding:12px 16px;border-top:1px solid var(--border);color:var(--ink-700)}td b{color:var(--navy);font-weight:600}
'''
W=[('Mon','Upper A'),('Tue','Lower A'),('Wed','Rest'),('Thu','Upper B'),('Fri','Lower B'),('Sat','Rest'),('Sun','Rest')]
N=[('Mon','4 meals','1,950 kcal'),('Tue','4 meals','1,950 kcal'),('Wed','4 meals','1,800 kcal'),('Thu','4 meals','1,950 kcal'),('Fri','4 meals','1,950 kcal'),('Sat','4 meals','1,800 kcal'),('Sun','4 meals','1,800 kcal')]
wd=''.join(f'<div class="{"rs" if v=="Rest" else ""}{" td" if d=="Sun" else ""}">{d}<b>{v}</b></div>' for d,v in W)
nd=''.join(f'<div class="{"td" if d=="Sun" else ""}">{d}<b>{v}</b>{k}</div>' for d,v,k in N)
prog=f'''<section class="prog" aria-label="Current program"><div class="prh"><div class="sp"><div class="lab">ROHAN'S CURRENT PROGRAM</div><div class="row" style="gap:10px;margin-top:4px"><b class="b" style="font-size:20px;font-weight:600">Fat loss · phase 2</b><span class="chip pos">{ic("check",12,w=2.4)}Active</span></div><div class="sm muted" style="margin-top:2px">Week 6 of 8 · Mon 21 Sep – Sun 15 Nov · what Rohan sees in his app today</div></div><div class="col" style="align-items:flex-end;gap:4px"><span class="chip sel">{ic("cal",12)}Next: phase 3 from Mon 16 Nov</span></div></div>
<div class="part"><div class="pl"><span class="pi">{ic("dumbbell",20)}</span><div><b>WORKOUT</b><strong>4 sessions a week</strong><span>Fat loss · phase 2 · v2 · since Mon 21 Sep</span></div></div><div class="days">{wd}</div><a class="btn o sm">Open builder</a></div>
<div class="part"><div class="pl"><span class="pi">{ic("utensils",20)}</span><div><b>NUTRITION</b><strong>1,950 kcal · 4 meals a day</strong><span>Fat loss 1,950 · v3 · since Mon 5 Oct</span></div></div><div class="days">{nd}</div><a class="btn o sm">Open builder</a></div></section>'''
V=[('dumbbell','Fat loss · phase 3','Workout','v1','<span class="chip sel">Scheduled</span>','From Mon 16 Nov','You · Sat 17 Oct'),('utensils','Fat loss 1,950','Nutrition','v3','<span class="chip pos">Active</span>','Mon 5 Oct – ongoing','You · Sun 4 Oct'),('dumbbell','Fat loss · phase 2','Workout','v2','<span class="chip pos">Active</span>','Mon 21 Sep – Sun 15 Nov','You · Sat 19 Sep'),('utensils','Fat loss 2,050','Nutrition','v2','<span class="chip neu">Superseded</span>','Mon 14 Sep – Sun 4 Oct','You · Sun 13 Sep'),('dumbbell','Fat loss · phase 1','Workout','v1','<span class="chip neu">Superseded</span>','Mon 24 Aug – Sun 20 Sep','You · Sat 22 Aug')]
rows=''.join(f'<tr><td><span class="row" style="gap:8px">{ic(i,15)}<b>{n}</b></span></td><td>{t}</td><td>{v}</td><td>{s}</td><td>{e}</td><td>{p}</td><td style="text-align:right"><a style="color:var(--indigo);font-weight:600">View</a></td></tr>' for i,n,t,v,s,e,p in V)
vers=f'<section class="wc" style="overflow:hidden"><div class="row" style="padding:14px 16px"><b class="b" style="font-size:17px">Versions</b><span class="sp"></span><div class="seg2"><a class="on">All</a><a>Workout</a><a>Nutrition</a></div><a class="pill2">Status {ic("down",14)}</a><span class="sm muted">5 of 5</span></div><table><tr><th>Plan</th><th>Part</th><th>Version</th><th>Status</th><th>Effective</th><th>Published</th><th></th></tr>{rows}</table></section>'
bar=f'<div class="row"><div class="seg2"><a class="on">{ic("clip",15)}&nbsp;Plans</a><a>Coaching setup</a></div><span class="sp"></span><a class="btn o sm">Replace from template</a><a class="btn p sm">{ic("edit",16)}Adjust plan</a></div>'
save('150-trainer-web-plan-v3-web',wpage('rohan',bar+prog+vers,'Plan',extra=X))
